"""Render all application and observability manifests from reviewable definitions."""
from pathlib import Path
import json,yaml
ROOT=Path(__file__).resolve().parents[1]
ns='wattshift'
def meta(name):return {'name':name,'namespace':ns,'labels':{'app.kubernetes.io/part-of':'wattshift'}}
def deployment(name,image,port=None,command=None,env=None,mounts=None,volumes=None,service_account=None):
 c={'name':name,'image':image,'imagePullPolicy':'IfNotPresent','resources':{'requests':{'cpu':'100m','memory':'128Mi'},'limits':{'cpu':'2','memory':'1Gi'}}}
 if port:c['ports']=[{'containerPort':port}]
 if command:c['command']=command
 if env:c['env']=env
 if mounts:c['volumeMounts']=mounts
 pod={'containers':[c]}
 if volumes:pod['volumes']=volumes
 if service_account:pod['serviceAccountName']=service_account
 if image.startswith('wattshift/backend'):pod['securityContext']={'runAsUser':10001,'runAsGroup':10001,'fsGroup':10001}
 return {'apiVersion':'apps/v1','kind':'Deployment','metadata':meta(name),'spec':{'replicas':1,'selector':{'matchLabels':{'app':name}},'template':{'metadata':{'labels':{'app':name,'app.kubernetes.io/part-of':'wattshift'}},'spec':pod}}}
def service(name,port,target=None):return {'apiVersion':'v1','kind':'Service','metadata':meta(name),'spec':{'selector':{'app':name},'ports':[{'port':port,'targetPort':target or port}]}}
def config(name,data):return {'apiVersion':'v1','kind':'ConfigMap','metadata':meta(name),'data':data}
backend='wattshift/backend:1.0.0-rc4';frontend='wattshift/console:1.0.0-rc4'
mounts=[{'name':'data','mountPath':'/data'}];volumes=[{'name':'data','persistentVolumeClaim':{'claimName':'wattshift-data'}}]
env=[{'name':'WATTSHIFT_DATA','value':'/data'}]
docs=[{'apiVersion':'v1','kind':'PersistentVolumeClaim','metadata':meta('wattshift-data'),'spec':{'accessModes':['ReadWriteOnce'],'resources':{'requests':{'storage':'2Gi'}}}},config('wattshift-settings',{'DATA_MODE':'live-snapshot','REGION':'DE','TIMEZONE':'Europe/Berlin'})]
api=deployment('wattshift-api',backend,8000,env=env,mounts=mounts,volumes=volumes)
pod=api['spec']['template']['spec'];pod['initContainers']=[{'name':'seed','image':backend,'command':['python','-c',"from pathlib import Path; import shutil; p=Path('/data/console.json'); shutil.copyfile('/app/seed/console.json',p) if not p.exists() else None"],'volumeMounts':mounts}]
c=pod['containers'][0];c['env'].append({'name':'WATTSHIFT_ALLOW_STALE_DEMO','value':'1'});c['readinessProbe']={'httpGet':{'path':'/ready','port':8000},'initialDelaySeconds':5,'periodSeconds':10};c['livenessProbe']={'httpGet':{'path':'/health','port':8000},'initialDelaySeconds':15,'periodSeconds':20};c['envFrom']=[{'configMapRef':{'name':'wattshift-settings'}}]
docs += [api,service('wattshift-api',8000),deployment('wattshift-console',frontend,80),service('wattshift-console',80)]
docs += [{'apiVersion':'batch/v1','kind':'CronJob','metadata':meta('wattshift-ingest'),'spec':{'schedule':'20 13 * * *','timeZone':'Europe/Berlin','concurrencyPolicy':'Forbid','startingDeadlineSeconds':3600,'successfulJobsHistoryLimit':2,'failedJobsHistoryLimit':3,'jobTemplate':{'spec':{'backoffLimit':2,'activeDeadlineSeconds':2400,'template':{'spec':{'restartPolicy':'OnFailure','securityContext':{'runAsUser':10001,'fsGroup':10001},'containers':[{'name':'ingest','image':backend,'command':['python','-m','wattshift.refresh'],'env':env,'volumeMounts':mounts,'resources':{'requests':{'cpu':'250m','memory':'512Mi'},'limits':{'cpu':'2','memory':'2Gi'}}}],'volumes':volumes}}}}}}]
# Kueue admission guard: new Workloads start with a Pending check.
# The WattShift controller alone marks it Ready via Workload/status. Never patch Job.suspend.
docs += [{'apiVersion':'v1','kind':'ServiceAccount','metadata':meta('wattshift-controller')},{'apiVersion':'rbac.authorization.k8s.io/v1','kind':'Role','metadata':meta('wattshift-controller'),'rules':[{'apiGroups':['kueue.x-k8s.io'],'resources':['workloads'],'verbs':['get','list']},{'apiGroups':['kueue.x-k8s.io'],'resources':['workloads/status'],'verbs':['get','patch']},{'apiGroups':['batch'],'resources':['jobs'],'verbs':['get','list']}]},{'apiVersion':'rbac.authorization.k8s.io/v1','kind':'RoleBinding','metadata':meta('wattshift-controller'),'subjects':[{'kind':'ServiceAccount','name':'wattshift-controller','namespace':ns}],'roleRef':{'apiGroup':'rbac.authorization.k8s.io','kind':'Role','name':'wattshift-controller'}}]
docs += [{'apiVersion':'rbac.authorization.k8s.io/v1','kind':'ClusterRole','metadata':{'name':'wattshift-admissioncheck-status'},'rules':[{'apiGroups':['kueue.x-k8s.io'],'resources':['admissionchecks'],'verbs':['get']},{'apiGroups':['kueue.x-k8s.io'],'resources':['admissionchecks/status'],'verbs':['get','patch']}]},{'apiVersion':'rbac.authorization.k8s.io/v1','kind':'ClusterRoleBinding','metadata':{'name':'wattshift-admissioncheck-status'},'subjects':[{'kind':'ServiceAccount','name':'wattshift-controller','namespace':ns}],'roleRef':{'apiGroup':'rbac.authorization.k8s.io','kind':'ClusterRole','name':'wattshift-admissioncheck-status'}}]
controller=deployment('wattshift-controller',backend,command=['python','-m','wattshift.controller'],env=env,mounts=mounts,volumes=volumes,service_account='wattshift-controller');docs.append(controller)
queue=[{'apiVersion':'kueue.x-k8s.io/v1beta2','kind':'AdmissionCheck','metadata':{'name':'wattshift-forecast'},'spec':{'controllerName':'wattshift.dev/forecast-admission'}}, {'apiVersion':'kueue.x-k8s.io/v1beta2','kind':'ResourceFlavor','metadata':{'name':'wattshift-cpu'},'spec':{'nodeLabels':{'kubernetes.io/os':'linux'}}},{'apiVersion':'kueue.x-k8s.io/v1beta2','kind':'ClusterQueue','metadata':{'name':'wattshift-cpu'},'spec':{'namespaceSelector':{'matchLabels':{'app.kubernetes.io/part-of':'wattshift'}},'admissionChecks':['wattshift-forecast'],'resourceGroups':[{'coveredResources':['cpu','memory'],'flavors':[{'name':'wattshift-cpu','resources':[{'name':'cpu','nominalQuota':'1'},{'name':'memory','nominalQuota':'1Gi'}]}]}]}},{'apiVersion':'kueue.x-k8s.io/v1beta2','kind':'LocalQueue','metadata':meta('wattshift'),'spec':{'clusterQueue':'wattshift-cpu'}}]
# Traefik ingress only for the local demo. Dashboard is not enabled.
docs += [{'apiVersion':'v1','kind':'ServiceAccount','metadata':meta('wattshift-ingress')},{'apiVersion':'rbac.authorization.k8s.io/v1','kind':'ClusterRole','metadata':{'name':'wattshift-ingress'},'rules':[{'apiGroups':[''],'resources':['services','endpoints','secrets','nodes'],'verbs':['get','list','watch']},{'apiGroups':['discovery.k8s.io'],'resources':['endpointslices'],'verbs':['get','list','watch']},{'apiGroups':['networking.k8s.io'],'resources':['ingresses','ingressclasses'],'verbs':['get','list','watch']},{'apiGroups':['networking.k8s.io'],'resources':['ingresses/status'],'verbs':['update']} ]},{'apiVersion':'rbac.authorization.k8s.io/v1','kind':'ClusterRoleBinding','metadata':{'name':'wattshift-ingress'},'subjects':[{'kind':'ServiceAccount','name':'wattshift-ingress','namespace':ns}],'roleRef':{'apiGroup':'rbac.authorization.k8s.io','kind':'ClusterRole','name':'wattshift-ingress'}}]
traefik=deployment('wattshift-ingress','traefik:v3.6.2',8000,service_account='wattshift-ingress');tc=traefik['spec']['template']['spec']['containers'][0];tc['args']=['--providers.kubernetesingress=true','--providers.kubernetesingress.ingressclass=wattshift','--providers.kubernetesingress.namespaces=wattshift','--entrypoints.web.address=:8000','--log.level=INFO'];tc['ports'][0]['hostPort']=80
docs += [traefik,{'apiVersion':'networking.k8s.io/v1','kind':'IngressClass','metadata':{'name':'wattshift'},'spec':{'controller':'traefik.io/ingress-controller'}},{'apiVersion':'networking.k8s.io/v1','kind':'Ingress','metadata':meta('wattshift-console'),'spec':{'ingressClassName':'wattshift','rules':[{'http':{'paths':[{'path':'/','pathType':'Prefix','backend':{'service':{'name':'wattshift-console','port':{'number':80}}}}]}}]}}]
# Monitoring configuration and provisioned dashboard.
prom={'global':{'scrape_interval':'15s'},'scrape_configs':[{'job_name':'wattshift','static_configs':[{'targets':['wattshift-api:8000']}]},{'job_name':'prometheus','static_configs':[{'targets':['localhost:9090']}]}]}
panels=[]
for i,(title,expr,unit) in enumerate([('Market price · current interval','wattshift_price_eur_mwh','currencyEUR'),('Carbon · domestic estimate','wattshift_carbon_estimate_g_kwh','suffix:gCO₂e/kWh'),('Power · ASSUMED, not GPU measured','wattshift_assumed_job_power_watts','watt'),('Savings · simulated energy only','wattshift_simulated_savings_eur','currencyEUR'),('Data age','wattshift_data_age_seconds','s'),('API request rate','sum(rate(wattshift_api_requests_total[5m]))','reqps')]):
 panels.append({'id':i+1,'type':'timeseries','title':title,'gridPos':{'x':(i%2)*12,'y':(i//2)*8,'w':12,'h':8},'datasource':{'type':'prometheus','uid':'wattshift-prometheus'},'targets':[{'expr':expr,'refId':'A'}],'fieldConfig':{'defaults':{'unit':unit},'overrides':[]}})
dash={'uid':'wattshift','title':'WattShift — estimates and operations','schemaVersion':39,'version':1,'refresh':'15s','time':{'from':'now-1h','to':'now'},'panels':panels}
(ROOT/'observability/grafana-dashboard.json').write_text(json.dumps(dash,indent=2))
monitor=[config('wattshift-prometheus',{'prometheus.yml':yaml.safe_dump(prom)}),config('wattshift-grafana',{'datasources.yaml':yaml.safe_dump({'apiVersion':1,'datasources':[{'name':'Prometheus','uid':'wattshift-prometheus','type':'prometheus','access':'proxy','url':'http://wattshift-prometheus:9090','isDefault':True}]}),'dashboards.yaml':yaml.safe_dump({'apiVersion':1,'providers':[{'name':'wattshift','options':{'path':'/var/lib/grafana/dashboards'}}]})}),config('wattshift-dashboard',{'wattshift.json':json.dumps(dash)})]
pm=deployment('wattshift-prometheus','prom/prometheus:v3.15.0',9090,mounts=[{'name':'config','mountPath':'/etc/prometheus'}],volumes=[{'name':'config','configMap':{'name':'wattshift-prometheus'}}]);pm['spec']['template']['spec']['containers'][0]['args']=['--config.file=/etc/prometheus/prometheus.yml','--storage.tsdb.retention.time=2d']
graf=deployment('wattshift-grafana','grafana/grafana:12.1.1',3000,env=[{'name':'GF_SECURITY_ADMIN_PASSWORD','valueFrom':{'secretKeyRef':{'name':'grafana-admin','key':'password'}}}],mounts=[{'name':'provision','mountPath':'/etc/grafana/provisioning/datasources/datasources.yaml','subPath':'datasources.yaml'},{'name':'provision','mountPath':'/etc/grafana/provisioning/dashboards/dashboards.yaml','subPath':'dashboards.yaml'},{'name':'dashboards','mountPath':'/var/lib/grafana/dashboards'}],volumes=[{'name':'provision','configMap':{'name':'wattshift-grafana'}},{'name':'dashboards','configMap':{'name':'wattshift-dashboard'}}]);monitor += [pm,service('wattshift-prometheus',9090),graf,service('wattshift-grafana',3000)]
for name,items in [('platform.yaml',docs),('queues.yaml',queue),('observability.yaml',monitor)]:
 (ROOT/'infra/kubernetes'/name).write_text(yaml.safe_dump_all(items,sort_keys=False))
print('Rendered',len(docs)+len(queue)+len(monitor),'resources')
